using System;using System.IO;using System.Text;using System.Reflection;using System.Runtime.InteropServices;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
class RenderDocumentWork {
 static object Get(object o,string n,params object[] a){return o.GetType().InvokeMember(n,BindingFlags.GetProperty|BindingFlags.InvokeMethod,null,o,a);}
 static object Call(object o,string n,params object[] a){return o.GetType().InvokeMember(n,BindingFlags.InvokeMethod|BindingFlags.OptionalParamBinding,null,o,a);}
 static void Set(object o,string n,object v){o.GetType().InvokeMember(n,BindingFlags.SetProperty,null,o,new[]{v});}
 static int Count(object o){return Convert.ToInt32(Get(o,"Count"));}
 static string Text(object shape){object f=Get(shape,"TextFrame"),r=Get(f,"TextRange");string text=Convert.ToString(Get(r,"Text"));if(text.Trim().Length>0&&Convert.ToDouble(Get(r,"BoundHeight"))>Convert.ToDouble(Get(shape,"Height"))-Convert.ToDouble(Get(f,"MarginTop"))-Convert.ToDouble(Get(f,"MarginBottom"))+2)throw new Exception("Text overflow: "+text);return text;}
 [STAThread]static int Main(string[] args){string dir=Path.GetFullPath(args[0]);var rows=new JavaScriptSerializer().Deserialize<object[]>(File.ReadAllText(Path.Combine(dir,"manifest.json")));foreach(string mode in new[]{"Word","PowerPoint"}){object app=null,collection=null,doc=null;bool owned=false;
  try{object running=null;try{running=Marshal.GetActiveObject(mode+".Application");}catch(COMException){}if(running!=null)throw new Exception("An existing Office session is open; QA stopped without changing it.");app=Activator.CreateInstance(Type.GetTypeFromProgID(mode+".Application"));collection=Get(app,mode=="Word"?"Documents":"Presentations");if(Count(collection)!=0)throw new Exception("Unexpected open documents");owned=true;Set(app,"AutomationSecurity",3);Set(app,"DisplayAlerts",mode=="Word"?0:1);if(mode=="Word")Set(app,"Visible",false);
   foreach(Dictionary<string,object> row in rows){string fmt=(string)row["format"];if(mode=="Word"?fmt!="docx":fmt!="pptx"&&fmt!="ppt")continue;string name=(string)row["name"];if(!System.Text.RegularExpressions.Regex.IsMatch(name,@"^(report|summary|compare|create|edit|convert|stress)\.(docx|pptx|ppt)$"))throw new Exception("Only generated fixture names are allowed");string file=Path.Combine(dir,name);var text=new StringBuilder();
    if(mode=="Word"){doc=Call(collection,"Open",file,false,true,false);text.Append(Convert.ToString(Get(Get(doc,"Content"),"Text")));Call(doc,"ExportAsFixedFormat",file+".pdf",17);}
    else{doc=Call(collection,"Open",file,-1,0,0);object slides=Get(doc,"Slides");for(int i=1;i<=Count(slides);i++){object slide=Get(slides,"Item",i);if(Convert.ToInt32(Get(Get(Get(Get(slide,"Background"),"Fill"),"ForeColor"),"RGB"))!=0xffffff)throw new Exception("Non-neutral slide background");object shapes=Get(slide,"Shapes");for(int j=1;j<=Count(shapes);j++){object shape=Get(shapes,"Item",j);if(Convert.ToInt32(Get(shape,"HasTable"))==-1){object table=Get(shape,"Table");for(int r=1;r<=Count(Get(table,"Rows"));r++)for(int c=1;c<=Count(Get(table,"Columns"));c++)text.Append(Text(Get(Get(table,"Cell",r,c),"Shape"))).Append(' ');}else if(Convert.ToInt32(Get(shape,"HasTextFrame"))==-1)text.Append(Text(shape)).Append(' ');}}Call(doc,"SaveAs",file+".pdf",32,0);}
    foreach(string expected in (IEnumerable)row["expected"])if(!text.ToString().Contains(expected))throw new Exception(file+" missing: "+expected);foreach(string forbidden in (IEnumerable)row["forbidden"])if(text.ToString().Contains(forbidden))throw new Exception(file+" unexpected: "+forbidden);
    Call(doc,"Close",mode=="Word"?new object[]{0}:new object[0]);doc=null;Console.WriteLine(row["name"]+": read-only reopen, content and PDF rendering passed");
   }
  }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{try{if(doc!=null)Call(doc,"Close",mode=="Word"?new object[]{0}:new object[0]);}catch{}try{if(owned&&collection!=null&&Count(collection)==0)Call(app,"Quit");}catch{}doc=collection=app=null;GC.Collect();GC.WaitForPendingFinalizers();}
 }return 0;}
}
